static void load_paths(const char *file, char *buf, int *count)
{
    FILE *f = fopen(file, "r");
    char line[MAX_PATH];
    buf[0] = 0;
    *count = 0;
    if (!f) return;
    while (fgets(line, sizeof(line), f) && *count < 8) {
        int n = (int)strlen(line);
        while (n > 0 && (line[n-1] == '\n' || line[n-1] == '\r' || line[n-1] == ' ')) line[--n] = 0;
        if (!n) continue;
        strcpy(buf + (*count) * MAX_PATH, line);
        (*count)++;
    }
    fclose(f);
}

